<script setup lang="ts">
import { computed, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { systemByCode } from '../shared/systemCatalog'
const route=useRoute();const router=useRouter();const auth=useAuthStore();const code=computed(()=>String(route.meta.system||''));const system=computed(()=>systemByCode(code.value)!)
onMounted(async()=>{if(!auth.user)await auth.loadMe();if(!auth.canAccess(code.value))router.replace('/portal')})
const logout=async()=>{await auth.logout();router.replace('/login')}
</script>
<template><el-container v-if="system" :class="['system-shell',`system-${code}`]" :style="{'--accent':system.accent}"><el-aside width="248px"><div class="system-brand"><div class="system-symbol">{{system.shortName.slice(0,1)}}</div><div><b>{{system.shortName}}</b><small>{{system.name}}</small></div></div><div class="nav-label">业务工作区</div><el-menu router :default-active="$route.path"><el-menu-item v-for="item in system.menus" :key="item.route" :index="item.route">{{item.label}}</el-menu-item></el-menu><button class="portal-return" @click="router.push('/portal')">← 返回统一门户</button></el-aside><el-container><el-header><div class="header-title"><b>{{system.name}}</b><span>{{system.description}}</span></div><div class="header-user"><el-tag effect="plain">{{auth.user?.positionName||'业务用户'}}</el-tag><span>{{auth.user?.realName}}</span><el-button link type="primary" @click="logout">退出</el-button></div></el-header><el-main><router-view/></el-main></el-container></el-container></template>
